// Cloudflare entry: the OpenNext-built Next.js app, plus a cron job every minute that calls
// /api/cron (email/WhatsApp outbox and order housekeeping).
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { createHmac } from "node:crypto";

type Env = { CRON_SECRET?: string; CLERK_SECRET_KEY?: string; NEXT_PUBLIC_SITE_URL?: string };
// Same derivation as src/lib/secrets.ts
const cronSecret = (env: Env) =>
  env.CRON_SECRET || (env.CLERK_SECRET_KEY ? createHmac("sha256", env.CLERK_SECRET_KEY).update("gupta-enterprises:CRON_SECRET").digest("hex") : "");

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil: (p: Promise<unknown>) => void }) {
    const req = new Request(`${env.NEXT_PUBLIC_SITE_URL ?? "https://guptaenterpriseskohima.com"}/api/cron`, {
      method: "POST",
      headers: { "x-cron-secret": cronSecret(env) },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
